 void thermal(){base("🌡️ THERMAL WATCH 3.0","Trend • min • max • medel",true);float[]s=stats();note("Aktuellt: "+temp()+"°C");if(s[3]>0)note("Min "+s[0]+"°C • Max "+s[1]+"°C • Medel "+String.format(Locale.ROOT,"%.1f",s[2])+"°C • "+(int)s[3]+" mätningar\nTrend: "+trend());bt("Starta 1 minut",()->startWatch(12));bt("Starta 5 minuter",()->startWatch(60));bt("Starta 15 minuter",()->startWatch(180));bt("Starta 30 minuter",()->startWatch(360));sec("Senaste mätningar");note(p.getString("temps","Ingen historik"));bt("Rensa historik",()->{p.edit().remove("temps").apply();thermal();});}void startWatch(int n){final int[]c={0};watch=new Runnable(){public void run(){saveTemp(temp());if(++c[0]<n)h.postDelayed(this,5000);else{watch=null;toast("Thermal Watch klar");thermal();}}};h.post(watch);}void stop(){if(watch!=null){h.removeCallbacks(watch);watch=null;}}void saveTemp(float x){String now=new SimpleDateFormat("MM-dd HH:mm:ss",Locale.getDefault()).format(new Date());String old=p.getString("temps","");String n=now+" • "+x+"°C"+(old.isEmpty()?"":"\n"+old);String[]a=n.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(360,a.length);i++)b.append(a[i]).append("\n");p.edit().putString("temps",b.toString().trim()).apply();}float[]stats(){float mi=999,ma=-999,sum=0;int n=0;for(String l:p.getString("temps","").split("\n"))try{int a=l.indexOf("• ")+2,b=l.indexOf("°C");float x=Float.parseFloat(l.substring(a,b));mi=Math.min(mi,x);ma=Math.max(ma,x);sum+=x;n++;}catch(Exception e){}return n==0?new float[]{0,0,0,0}:new float[]{mi,ma,sum/n,n};}String trend(){String[]l=p.getString("temps","").split("\n");if(l.length<2)return"för lite data";try{float a=Float.parseFloat(l[0].substring(l[0].indexOf("• ")+2,l[0].indexOf("°C"))),b=Float.parseFloat(l[Math.min(l.length-1,11)].substring(l[Math.min(l.length-1,11)].indexOf("• ")+2,l[Math.min(l.length-1,11)].indexOf("°C")));return a>b+0.3?"↗ stigande":a<b-0.3?"↘ sjunkande":"→ stabil";}catch(Exception e){return"okänd";}}
