 boolean shInstalled(){try{getPackageManager().getPackageInfo("moe.shizuku.privileged.api",0);return true;}catch(Exception e){return false;}}boolean shOk(){try{return Shizuku.pingBinder()&&Shizuku.checkSelfPermission()==PackageManager.PERMISSION_GRANTED;}catch(Throwable e){return false;}}String shStatus(){if(!shInstalled())return"❌ Shizuku ej installerad";try{if(!Shizuku.pingBinder())return"⚠️ Shizuku-tjänsten är inte igång";}catch(Throwable e){return"⚠️ Shizuku ej redo";}return shOk()?"✅ Shizuku aktiv och behörig":"🟡 Shizuku-behörighet krävs";}void requestSh(){try{Shizuku.requestPermission(REQ);}catch(Throwable e){toast("Starta Shizuku först");}}boolean installed(String x){try{getPackageManager().getPackageInfo(x,0);return true;}catch(Exception e){return false;}}boolean enabled(String x){try{return getPackageManager().getApplicationInfo(x,0).enabled;}catch(Exception e){return false;}}boolean openPkg(String x){Intent i=getPackageManager().getLaunchIntentForPackage(x);if(i!=null){startActivity(i);return true;}return false;}void log(String s){String old=p.getString("history","");String n=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date())+" • "+s+(old.isEmpty()?"":"\n"+old);String[]a=n.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(60,a.length);i++)b.append(a[i]).append("\n");p.edit().putString("history",b.toString().trim()).apply();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
